-- MP-0034: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='amanah' and type='party') then raise exception 'MP-0034: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0034: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0034: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('aiman-athirah-sabu','lim-lip-eng','prabakaran-parameswaran') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0034: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('sepang','kepong','batu') and slug not in ('aiman-athirah-sabu','lim-lip-eng','prabakaran-parameswaran')) then raise exception 'MP-0034: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0034:%' and (m.source_type <> 'editorial' or e.slug not in ('aiman-athirah-sabu','lim-lip-eng','prabakaran-parameswaran') or m.import_key not like 'MP-0034:' || e.slug || ':%')) then raise exception 'MP-0034: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'aiman-athirah-sabu','Aiman Athirah Sabu','government','Deputy Minister of Housing and Local Government','Sepang','Selangor','Aiman Athirah Sabu represents Sepang, Selangor, in the Dewan Rakyat. Current role: Deputy Minister of Housing and Local Government. A AMANAH member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4152','/portraits/aiman-athirah-sabu.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/YB%20Sepang.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4152"}, {"label": "AMANAH · women’s chief, 21 August 2026", "url": "https://www.freemalaysiatoday.com/category/bahasa/tempatan/2026/08/21/peruntukan-sama-rata-perlu-kesepakatan-kerajaan-perpaduan-kata-pemimpin-amanah"}]'::jsonb from public.entities parent where parent.slug='amanah' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'lim-lip-eng','Lim Lip Eng','government','Member of the Dewan Rakyat','Kepong','Kuala Lumpur','Lim Lip Eng represents Kepong, Kuala Lumpur, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4153','/portraits/lim-lip-eng.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P114.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4153"}, {"label": "DAP · current Kuala Lumpur representatives", "url": "https://dapmalaysia.org/kuala-lumpur-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'prabakaran-parameswaran','Prabakaran Parameswaran','government','Member of the Dewan Rakyat','Batu','Kuala Lumpur','Prabakaran Parameswaran represents Batu, Kuala Lumpur, in the Dewan Rakyat. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4154','/portraits/prabakaran-parameswaran.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P115.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4154"}, {"label": "PKR · current representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('aiman-athirah-sabu','lim-lip-eng','prabakaran-parameswaran') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0034: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0034:aiman-athirah-sabu:sepang-school-supplies','Provide school-supply packages to 500 Sepang children','Education','achieved',null,null,null,null,'2026-01-10','https://www.bernama.com/bm/am/news.php?id=2510995','Aiman Athirah’s constituency centre reported packages worth RM183 each, delivered with Yayasan Taqwa MAIWP and the religious-affairs minister’s assistance.','Achieved covers the reported 500-child handover. The RM3.7 million wider constituency allocation and education budget are not this programme’s completion percentage.','2026-11-09','editorial',false from public.entities e where e.slug='aiman-athirah-sabu' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0034:aiman-athirah-sabu:ramadan-mosques-surau','Distribute Ramadan contributions to Sepang mosques and suraus','Social Welfare','achieved',null,null,null,null,'2026-02-20','https://harapandaily.com/2026/02/20/aiman-athirah-lancar-ihya-ramadan-sepang-rm490000-diperuntuk-untuk-40-masjid-dan-20-surau/','Aiman Athirah reported contributions to 40 mosques and about 20 Friday-prayer suraus at the 19 February Ihya Ramadan launch.','The reported institutional handover is complete. The RM490,380 overall Ramadan programme budget, later visits, rice distribution and planned March event are not all verified deliveries.','2026-11-09','editorial',false from public.entities e where e.slug='aiman-athirah-sabu' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0034:lim-lip-eng:seroja-resurfacing','Secure funding for resurfacing Seroja apartments’ road and parking area','Infrastructure','achieved',null,null,null,null,'2024-02-28','https://www.dbkl.gov.my/keratan-akhbar/lim-lip-eng-managed-to-receive-rm200k-allocation-seroja-apartments-parking-lot-and-road-repaved-china-press','A China Press clipping archived by DBKL reports RM200,000 secured by Lim Lip Eng and completed road and parking resurfacing at Seroja apartments.','A historical February 2024 delivery report involving ICU funding and council coordination. The headline and clipping were checked; later road condition and satisfaction were not independently measured.','2026-11-09','editorial',false from public.entities e where e.slug='lim-lip-eng' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

